// ---------------------------------------------------------------------------
// Datas (sempre 'aaaa-mm-dd', no fuso de São Paulo)
// ---------------------------------------------------------------------------

function hojeISO(agora) {
  // en-CA formata como aaaa-mm-dd
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(agora || new Date());
}

function partes(iso) { var p = iso.split('-').map(Number); return { y: p[0], m: p[1], d: p[2] }; }
function utc(iso) { var p = partes(iso); return Date.UTC(p.y, p.m - 1, p.d); }
function pad(n) { return (n < 10 ? '0' : '') + n; }
function deUtc(ms) { var t = new Date(ms); return t.getUTCFullYear() + '-' + pad(t.getUTCMonth() + 1) + '-' + pad(t.getUTCDate()); }
function somaDias(iso, n) { return deUtc(utc(iso) + n * 864e5); }
function diaDaSemana(iso) { return new Date(utc(iso)).getUTCDay(); } // 0 = domingo
function dias(ini, fim) { return Math.round((utc(fim) - utc(ini)) / 864e5) + 1; }
function br(iso) { var p = partes(iso); return pad(p.d) + '/' + pad(p.m) + '/' + p.y; }
function brCurto(iso) { var p = partes(iso); return pad(p.d) + '/' + pad(p.m); }

function semanaIso(iso) {
  var t = new Date(utc(iso));
  var dn = (t.getUTCDay() + 6) % 7;
  t.setUTCDate(t.getUTCDate() - dn + 3);
  var j4 = new Date(Date.UTC(t.getUTCFullYear(), 0, 4));
  return 1 + Math.round(((t - j4) / 864e5 - 3 + ((j4.getUTCDay() + 6) % 7)) / 7);
}

function segundaDaSemana(iso) { return somaDias(iso, -((diaDaSemana(iso) + 6) % 7)); }

/** "ter, 17/11" (com o ano só quando não é o ano corrente). */
function rotuloDia(iso, hoje) {
  var y = partes(iso).y;
  return DIAS_SEM[diaDaSemana(iso)] + ', ' + brCurto(iso) + (y !== partes(hoje).y ? '/' + y : '');
}
/** "10/11 a 16/11" (com o ano quando o período não é todo do ano corrente). */
function rotuloPeriodo(ini, fim, hoje) {
  if (ini === fim) return rotuloDia(ini, hoje);
  var y = partes(hoje).y, comAno = partes(ini).y !== y || partes(fim).y !== y;
  return brCurto(ini) + ' a ' + (comAno ? br(fim) : brCurto(fim));
}

// ---------------------------------------------------------------------------
// Interpretação do comando
// ---------------------------------------------------------------------------

function normaliza(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

/** Lê "dd/mm", "dd/mm/aa" ou "dd/mm/aaaa". Sem ano: o mais recente que não está no futuro. */
function lerData(dd, mm, aa, hoje) {
  var d = +dd, m = +mm, y;
  if (aa) { y = +aa; if (y < 100) y += 2000; } else y = partes(hoje).y;
  var iso = y + '-' + pad(m) + '-' + pad(d);
  var t = new Date(utc(iso));
  if (m < 1 || m > 12 || t.getUTCDate() !== d || t.getUTCMonth() !== m - 1) return null;
  if (!aa && iso > hoje) iso = (y - 1) + '-' + pad(m) + '-' + pad(d);
  return iso;
}

/**
 * Transforma a mensagem num comando.
 * Retorna { tipo: 'ajuda' } ou { tipo: 'resumo'|'defeitos'|'pendentes', ini, fim, rotulo, setor }
 * ou { tipo: 'erro', msg }.
 */
/** Resumo de uma semana inteira, k semanas para trás (0 = esta semana, até hoje). */
function cmdSemana(k, hoje) {
  var ini = somaDias(segundaDaSemana(hoje), -7 * k), fim = somaDias(ini, 6);
  if (fim > hoje) fim = hoje;
  return { tipo: 'resumo', ini: ini, fim: fim, setor: null,
    quando: k === 0 ? 'da semana' : k === 1 ? 'da semana passada' : 'da semana ' + semanaIso(ini),
    rotulo: 'Semana ' + semanaIso(ini) + ' · ' + rotuloPeriodo(ini, fim, hoje) };
}

/**
 * Resposta a "Escolher outra semana": número da semana ("45", "s45", "semana 45") ou uma data ("10/11").
 * Retorna o cmd da semana, { tipo: 'pedirSemana', erro } para perguntar de novo, ou null (não é resposta).
 */
function semanaDigitada(texto, hoje) {
  var s = normaliza(texto).replace(/^[\/!#.]+/, '').replace(/[.!]+$/, '').replace(/^(semana|sem|s)\s*/, '').trim();
  var k, m;
  if (/^\d{1,2}$/.test(s)) {
    var n = +s;
    if (n < 1 || n > 53) return { tipo: 'pedirSemana', erro: 'Não existe semana ' + n + '.' };
    for (k = 0; k <= SEMANAS_ATRAS; k++) if (semanaIso(somaDias(segundaDaSemana(hoje), -7 * k)) === n) return cmdSemana(k, hoje);
    return { tipo: 'pedirSemana', erro: 'Não achei a semana ' + n + '.' };
  }
  if ((m = s.match(/^(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](\d{2}|\d{4}))?$/))) {
    var iso = lerData(m[1], m[2], m[3], hoje);
    if (!iso) return { tipo: 'pedirSemana', erro: 'Data inválida: ' + s + '.' };
    if (iso > hoje) return { tipo: 'pedirSemana', erro: 'A data ' + br(iso) + ' ainda não chegou.' };
    k = Math.round((utc(segundaDaSemana(hoje)) - utc(segundaDaSemana(iso))) / (7 * 864e5));
    if (k > SEMANAS_ATRAS) return { tipo: 'pedirSemana', erro: 'Escolha uma semana do último ano.' };
    return cmdSemana(k, hoje);
  }
  return null;
}

/**
 * Resposta a "Qual setor?": "0" ou "todos" = todos; "1 3", "1,3", "1 e 3" ou "13" = vários.
 * Retorna { setores } (null = todos), { erro: true } ou null quando a mensagem não é resposta.
 */
function setoresDigitados(so) {
  if (/^todos?$/.test(so)) return { setores: null };
  if (!/^[\d\s,;+e\/.-]+$/.test(so)) return null;
  var nums = [];
  so.replace(/\be\b/g, ' ').split(/[^0-9]+/).filter(Boolean).forEach(function (d) {
    d.split('').forEach(function (x) { nums.push(+x); }); // "13" = 1 e 3 (só há setores de 1 a 5)
  });
  if (!nums.length) return null;
  if (nums.indexOf(0) >= 0) return { setores: null };
  if (nums.some(function (x) { return x < 1 || x > SETORES.length; })) return { erro: true };
  var ids = SETORES.filter(function (st, i) { return nums.indexOf(i + 1) >= 0; }).map(function (st) { return st.id; });
  return { setores: ids.length === SETORES.length ? null : ids };
}

function perguntarSetor(pendente, naoEntendi) {
  return naoEntendi ? { tipo: 'escolherSetor', pendente: pendente, naoEntendi: true } : { tipo: 'escolherSetor', pendente: pendente };
}

/**
 * etapa = o que o bot perguntou por último nesta conversa ({ qual, pendente } ou só o texto de qual):
 *   'semana'      → "Qual semana?" (1 esta, 2 a passada, 3 escolher outra)
 *   'qualSemana'  → "Digite a semana" (número da semana ou uma data)
 *   'setor'       → "Qual setor?" (pendente = o relatório que vai sair depois da resposta)
 * Com etapa, a mensagem responde à pergunta; o que não for resposta segue o caminho normal.
 */
function interpretar(texto, hoje, etapa) {
  var qual = typeof etapa === 'string' ? etapa : (etapa && etapa.qual) || null;
  // Número ("3", "/3", "3️⃣"); 0 = menu (na pergunta do setor, 0 = todos).
  var so = normaliza(texto).replace(/[️⃣]/g, '').replace(/^[\/!#.]+/, '').replace(/[.)!]+$/, '').trim();
  if (qual === 'setor' && etapa.pendente) {
    var rs = setoresDigitados(so);
    if (rs && rs.erro) return perguntarSetor(etapa.pendente, true);
    if (rs) { var c = JSON.parse(JSON.stringify(etapa.pendente)); c.setores = rs.setores; c.setor = null; return c; }
  }
  if (so === '0') return { tipo: 'ajuda' };
  if (qual === 'qualSemana') {
    var sd = semanaDigitada(so, hoje);
    if (sd) return sd.tipo === 'resumo' ? perguntarSetor(sd) : sd;
  }
  if (/^\d{1,2}$/.test(so)) {
    var op = +so;
    if (qual === 'semana') {
      if (op === 1 || op === 2) return perguntarSetor(cmdSemana(op - 1, hoje));
      return op === 3 ? { tipo: 'pedirSemana' } : { tipo: 'escolherSemana', naoEntendi: true };
    }
    var it = MENU[op - 1];
    if (!it) return { tipo: 'ajuda', naoEntendi: true };
    if (!it[1]) return { tipo: 'escolherSemana' };
    return it[2] ? perguntarSetor(interpretar(it[1], hoje)) : interpretar(it[1], hoje);
  }

  var s = ' ' + normaliza(texto).replace(/^[\/!#.]+/, '') + ' ';

  // setor (apelidos mais longos primeiro, para "madeirado uv" ganhar de "uv")
  var setor = null, lista = [];
  SETORES.forEach(function (st) { st.apelidos.forEach(function (a) { lista.push([a, st.id]); }); });
  lista.sort(function (a, b) { return b[0].length - a[0].length; });
  for (var i = 0; i < lista.length && !setor; i++) {
    var re = new RegExp('(^|[^a-z0-9])' + lista[i][0].replace(/[-]/g, '\\-') + '(?=[^a-z0-9]|$)');
    if (re.test(s)) { setor = lista[i][1]; s = s.replace(re, '$1 '); }
  }

  // datas explícitas
  var datas = [], m, reData = /(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](\d{2}|\d{4}))?(?!\d)/g;
  while ((m = reData.exec(s)) && datas.length < 3) {
    var iso = lerData(m[1], m[2], m[3], hoje);
    if (!iso) return { tipo: 'erro', msg: 'Data inválida: ' + m[0] };
    datas.push(iso);
  }
  s = s.replace(reData, ' ');

  var palavras = s.split(/[^a-z0-9]+/).filter(Boolean);
  function tem() { for (var j = 0; j < arguments.length; j++) if (palavras.indexOf(arguments[j]) >= 0) return true; return false; }

  if (!palavras.length && !datas.length && !setor) return { tipo: 'ajuda' };
  if (tem('comandos', 'mais', 'outros')) return { tipo: 'comandos' };
  if (tem('ajuda', 'menu', 'help', 'opcoes', 'oi', 'ola', 'bom', 'boa', 'start')) return { tipo: 'ajuda' };

  var tipo = 'resumo';
  if (tem('defeito', 'defeitos', 'codigos', 'codigo', 'top')) tipo = 'defeitos';
  else if (tem('pendente', 'pendentes', 'pendencia', 'pendencias', 'faltando', 'falta', 'faltam')) tipo = 'pendentes';

  // quando = fim do título ("Resumo da semana", "Defeitos de ontem"); rotulo = linha de baixo, com as datas.
  var anterior = tem('passada', 'passado', 'anterior', 'ultima', 'ultimo');
  var ini, fim, quando, rotulo;
  if (datas.length >= 2) {
    ini = datas[0] < datas[1] ? datas[0] : datas[1];
    fim = datas[0] < datas[1] ? datas[1] : datas[0];
    quando = 'do período';
  } else if (datas.length === 1) {
    ini = fim = datas[0];
    quando = 'do dia';
  } else if (tem('ontem')) {
    ini = fim = somaDias(hoje, -1);
    quando = 'de ontem';
  } else if (tem('semana', 'semanal')) {
    ini = segundaDaSemana(hoje);
    if (anterior) { ini = somaDias(ini, -7); fim = somaDias(ini, 6); } else fim = hoje;
    quando = anterior ? 'da semana passada' : 'da semana';
    rotulo = 'Semana ' + semanaIso(ini) + ' · ' + rotuloPeriodo(ini, fim, hoje);
  } else if (tem('mes', 'mensal')) {
    var p = partes(hoje);
    if (anterior) {
      var y = p.m === 1 ? p.y - 1 : p.y, mm = p.m === 1 ? 12 : p.m - 1;
      ini = y + '-' + pad(mm) + '-01'; fim = somaDias(p.y + '-' + pad(p.m) + '-01', -1);
    } else { ini = p.y + '-' + pad(p.m) + '-01'; fim = hoje; }
    quando = anterior ? 'do mês passado' : 'do mês';
    rotulo = MESES[partes(ini).m - 1] + ' · ' + rotuloPeriodo(ini, fim, hoje);
  } else if (tem('hoje', 'dia', 'agora', 'resumo', 'relatorio', 'defeito', 'defeitos', 'codigos', 'codigo', 'top',
                 'pendente', 'pendentes', 'pendencia', 'pendencias', 'faltando', 'falta', 'faltam') || setor) {
    ini = fim = hoje;
    quando = 'de hoje';
  } else {
    return { tipo: 'ajuda', naoEntendi: true };
  }

  if (ini > hoje) return { tipo: 'erro', msg: 'A data ' + br(ini) + ' ainda não chegou.' };
  if (fim > hoje) fim = hoje;
  if (dias(ini, fim) > MAX_DIAS) return { tipo: 'erro', msg: 'Período grande demais (máximo ' + MAX_DIAS + ' dias).' };
  if (tipo === 'pendentes' && ini !== fim) { ini = fim; rotulo = null; }
  if (!rotulo) rotulo = rotuloPeriodo(ini, fim, hoje);

  return { tipo: tipo, ini: ini, fim: fim, quando: quando, rotulo: rotulo, setor: setor };
}

// ---------------------------------------------------------------------------
// Cálculo
// ---------------------------------------------------------------------------

/** Setores escolhidos: lista de ids, ou null = todos. (cmd.setor vem do comando digitado, cmd.setores do menu.) */
function sel(cmd) { return cmd.setores && cmd.setores.length ? cmd.setores : (cmd.setor ? [cmd.setor] : null); }
function unico(cmd) { var s = sel(cmd); return s && s.length === 1 ? s[0] : null; }

function filtrar(registros, cmd) {
  var s = sel(cmd);
  return (registros || []).filter(function (r) {
    return r && r.data >= cmd.ini && r.data <= cmd.fim && (!s || s.indexOf(r.setor) >= 0);
  });
}

/**
 * Soma um conjunto de lançamentos.
 * Refugo % = ruins / produção, só com lançamentos contados em peças
 * (em pilhas não dá para comparar, como no formulário e na planilha).
 */
function agrega(regs) {
  var a = { n: 0, pecas: 0, pilhas: 0, ruins: 0, ruinsPeca: 0, defeitos: {}, turnos: {} };
  regs.forEach(function (r) {
    a.n++;
    a.ruins += r.ruins || 0;
    a.turnos[r.turno] = (a.turnos[r.turno] || 0) + 1;
    if (r.unidade === 'Pilha') a.pilhas += r.producao || 0;
    else if (r.producao !== null && r.producao !== undefined) { a.pecas += r.producao; a.ruinsPeca += r.ruins || 0; }
    Object.keys(r.defeitos || {}).forEach(function (c) { a.defeitos[c] = (a.defeitos[c] || 0) + r.defeitos[c]; });
  });
  a.refugo = a.pecas > 0 ? a.ruinsPeca / a.pecas : null;
  return a;
}

function topDefeitos(defs, n) {
  return Object.keys(defs).map(function (c) { return [c, defs[c]]; })
    .sort(function (a, b) { return b[1] - a[1] || Number(a[0].slice(1)) - Number(b[0].slice(1)); })
    .slice(0, n);
}

// ---------------------------------------------------------------------------
// Texto (formatação do WhatsApp: *negrito*, _itálico_)
// ---------------------------------------------------------------------------

function num(n) { return String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }
function nomeSetor(id) { for (var i = 0; i < SETORES.length; i++) if (SETORES[i].id === id) return SETORES[i].nome; return id; }
function curtoSetor(id) { for (var i = 0; i < SETORES.length; i++) if (SETORES[i].id === id) return SETORES[i].curto; return id; }
function descDefeito(c) { return DEFEITOS[c] ? c + ' ' + DEFEITOS[c] : c; }
function lista(a) { return a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' e ' + a[a.length - 1]; }
function maiuscula(s) { return s.charAt(0).toUpperCase() + s.slice(1); }

function pecasRuins(n) { return num(n) + (n === 1 ? ' peça ruim' : ' peças ruins'); }
function lancamentos(n) { return n + (n === 1 ? ' lançamento' : ' lançamentos'); }
/** "22 ruins · 3 lançamentos": o que vai nas linhas de setor, turno e dia. */
function ruinsLanc(a) { return num(a.ruins) + (a.ruins === 1 ? ' ruim' : ' ruins') + ' · ' + lancamentos(a.n); }

/** "Resumo da semana", "Defeitos de ontem" (sem os setores). */
function tituloBase(cmd) { return (cmd.tipo === 'defeitos' ? 'Defeitos' : 'Resumo') + (cmd.quando ? ' ' + cmd.quando : ''); }

/** "Resumo da semana", "Tagliabue · Resumo de hoje", "Tagliabue e Polimento · Resumo de hoje". */
function tituloDe(cmd) {
  var s = sel(cmd);
  return s ? lista(s.map(curtoSetor)) + ' · ' + tituloBase(cmd) : tituloBase(cmd);
}

function cabecalho(cmd, emoji, titulo) {
  return emoji + ' *' + titulo + '*\n_' + cmd.rotulo + '_';
}

/** Principais defeitos, um por linha: "Q72 Pintura escorrida · 12". */
function blocoDefeitos(defs, n) {
  var top = topDefeitos(defs, n);
  if (!top.length) return [];
  return ['', '*Principais defeitos*'].concat(top.map(function (d) { return descDefeito(d[0]) + ' · ' + num(d[1]); }));
}

/** Setor/turno sem nenhum lançamento no dia. */
function faltando(registros, dia) {
  var out = [];
  SETORES.forEach(function (st) {
    var t = (TURNOS_ESPERADOS[st.id] || []).filter(function (turno) {
      return !registros.some(function (r) { return r.data === dia && r.setor === st.id && r.turno === turno; });
    });
    if (t.length) out.push({ setor: st.id, turnos: t });
  });
  return out;
}

/** Linhas "Noite: Tagliabue, IBOTIC e Madeirado UV" agrupando os setores pelos turnos que faltam. */
function linhasFaltando(registros, cmd) {
  var s = sel(cmd);
  var f = faltando(registros, cmd.fim).filter(function (x) { return !s || s.indexOf(x.setor) >= 0; });
  var grupos = {}, ordem = [];
  f.forEach(function (x) {
    var k = maiuscula(x.turnos.join(' e ').toLowerCase());
    if (!grupos[k]) { grupos[k] = []; ordem.push(k); }
    grupos[k].push(curtoSetor(x.setor));
  });
  return ordem.map(function (k) { return k + ': ' + lista(grupos[k]); });
}

function blocoFaltando(registros, cmd, hoje) {
  if (cmd.ini !== cmd.fim) return [];
  var l = linhasFaltando(registros, cmd);
  if (!l.length) return [];
  return ['', cmd.fim === hoje ? '⏳ *Ainda sem lançamento*' : '⚠️ *Sem lançamento*'].concat(l);
}

/**
 * Resumo em texto: só peças ruins e lançamentos (a produção vai na foto; refugo % não entra),
 * por setor (ou, com um setor só, por turno e por dia) e os principais defeitos.
 */
function relatorioResumo(cmd, registros, hoje) {
  var regs = filtrar(registros, cmd), total = agrega(regs), s = sel(cmd), um = unico(cmd);
  var L = [cabecalho(cmd, '📊', tituloDe(cmd)), ''];

  if (!regs.length) {
    L.push('Nenhum lançamento ' + (cmd.ini === cmd.fim ? 'neste dia.' : 'no período.'));
  } else {
    L.push('*' + pecasRuins(total.ruins) + '* · ' + lancamentos(total.n));
    if (!um) {
      L.push('', '*Setores*');
      SETORES.filter(function (st) { return !s || s.indexOf(st.id) >= 0; }).forEach(function (st) {
        var rs = regs.filter(function (r) { return r.setor === st.id; });
        L.push('• ' + st.curto + ' · ' + (rs.length ? ruinsLanc(agrega(rs)) : '_sem lançamento_'));
      });
    } else {
      L.push('', '*Turnos*');
      ['Dia', 'Noite'].forEach(function (t) {
        var at = agrega(regs.filter(function (r) { return r.turno === t; }));
        L.push((t === 'Dia' ? '☀️ ' : '🌙 ') + t + ' · ' + (at.n ? ruinsLanc(at) : '_sem lançamento_'));
      });
      if (cmd.ini !== cmd.fim) {
        L.push('', '*Por dia*');
        for (var d = cmd.ini; d <= cmd.fim; d = somaDias(d, 1)) {
          var ad = agrega(regs.filter(function (r) { return r.data === d; }));
          if (ad.n) L.push(DIAS_SEM[diaDaSemana(d)] + ' ' + brCurto(d) + ' · ' + ruinsLanc(ad));
        }
      }
    }
    L = L.concat(blocoDefeitos(total.defeitos, um ? 5 : 3));
  }

  if (!um) L = L.concat(blocoFaltando(registros, cmd, hoje)); // com um setor só, os turnos já mostram
  return L.join('\n');
}

function relatorioDefeitos(cmd, registros) {
  var regs = filtrar(registros, cmd), a = agrega(regs), s = sel(cmd);
  var L = [cabecalho(cmd, '🔎', tituloDe(cmd)), ''];
  var top = topDefeitos(a.defeitos, 8);
  if (!top.length) {
    L.push(regs.length ? 'Nenhum defeito lançado. 👏' : 'Nenhum lançamento ' + (cmd.ini === cmd.fim ? 'neste dia.' : 'no período.'));
    return L.join('\n');
  }
  L.push('*' + pecasRuins(a.ruins) + '* · ' + lancamentos(a.n), '');
  top.forEach(function (d, i) {
    L.push((i + 1) + '. ' + descDefeito(d[0]) + ' · *' + num(d[1]) + '*' + (a.ruins ? ' (' + Math.round(100 * d[1] / a.ruins) + '%)' : ''));
  });
  if (!unico(cmd)) {
    L.push('', '*Por setor*');
    SETORES.filter(function (st) { return !s || s.indexOf(st.id) >= 0; }).forEach(function (st) {
      var as = agrega(regs.filter(function (r) { return r.setor === st.id; }));
      var t1 = topDefeitos(as.defeitos, 1)[0];
      if (as.ruins) L.push('• ' + st.curto + ' · ' + num(as.ruins) + ' ruins' + (t1 ? ' · mais comum ' + t1[0] : ''));
    });
  }
  return L.join('\n');
}

function relatorioPendentes(cmd, registros, hoje) {
  var l = linhasFaltando(registros, cmd);
  var titulo = cmd.fim === hoje ? 'Quem ainda não lançou' : 'Quem não lançou';
  return [cabecalho(cmd, '⏳', titulo), ''].concat(l.length ? l : ['✅ Todos os setores já lançaram, dia e noite.']).join('\n');
}

// ---------------------------------------------------------------------------
// Conversa: "relatorio" liga o bot naquela conversa, "sair" desliga.
// Fora disso o bot fica em silêncio (o número pode ser usado para conversar normalmente).
// ---------------------------------------------------------------------------

var SESSAO_MINUTOS = 30; // desliga sozinho depois desse tempo sem mensagens

/**
 * Decide o que fazer com a mensagem conforme a conversa está ligada ou não.
 * ativoAte = até quando a conversa está ligada (ms) ou vazio; grupo = mensagem de grupo.
 * Retorna { acao: 'abrir'|'sair'|'comando'|'ignorar', resto, ativoAte }.
 * Em grupo não há liga/desliga: a barra (/hoje) já indica que é com o bot.
 */
function controleSessao(texto, ativoAte, agoraMs, grupo) {
  var s = normaliza(texto).replace(/^[\/!#.]+/, '').trim();
  var m = s.match(/^(relatorios?|sair)(?![a-z0-9])[\s,.;:!?-]*(.*)$/);
  var palavra = m ? m[1].replace(/s$/, '') : null;
  var ativo = !!ativoAte && ativoAte > agoraMs;
  var renova = agoraMs + SESSAO_MINUTOS * 60000;
  if (palavra === 'relatorio') return { acao: 'abrir', resto: m[2].trim(), ativoAte: renova };
  if (palavra === 'sair') return { acao: grupo || !ativo ? 'ignorar' : 'sair', ativoAte: null };
  if (grupo) return { acao: 'comando', resto: texto, ativoAte: null };
  return ativo ? { acao: 'comando', resto: texto, ativoAte: renova } : { acao: 'ignorar', ativoAte: null };
}

function textoSair() {
  return '👋 Relatórios encerrados.\nPara voltar, mande *relatorio*.';
}

/** Primeira mensagem ao ligar ("relatorio") e resposta a "menu", "0" ou mensagem não entendida. */
function menu(naoEntendi, grupo) {
  return (naoEntendi ? 'Não entendi 🤔\n\n' : '') +
    '📊 *Buy Off · Pintura*\nEscolha uma opção:\n\n' +
    MENU.map(function (m, i) { return EMOJI_NUM[i + 1] + ' ' + m[0]; }).join('\n') + '\n\n' +
    (grupo ? 'Responda com barra e o número (ex.: */1*)' : 'Responda só com o número · *sair* para encerrar');
}

/** "Qual semana?": esta semana, a passada (com as datas) ou escolher outra. */
function textoEscolherSemana(naoEntendi, grupo, hoje) {
  var esta = cmdSemana(0, hoje), passada = cmdSemana(1, hoje);
  return (naoEntendi ? 'Não entendi 🤔\n\n' : '') +
    '📅 *Resumo semanal*\nQual semana?\n\n' +
    '1️⃣ Esta semana · ' + brCurto(esta.ini) + ' até hoje\n' +
    '2️⃣ Semana passada · ' + rotuloPeriodo(passada.ini, passada.fim, hoje) + '\n' +
    '3️⃣ Escolher outra semana\n\n' +
    (grupo ? 'Responda com barra e o número (ex.: */1*) · */0* volta ao menu' : 'Responda só com o número · *0* volta ao menu');
}

/** "Escolher outra semana": pede o número da semana ou uma data. */
function textoPedirSemana(erro, grupo, hoje) {
  var b = grupo ? '/' : '';
  return (erro ? '⚠️ ' + erro + '\n\n' : '') +
    '📅 *Escolher semana*\nDigite o número da semana (ex.: *' + b + semanaIso(somaDias(hoje, -14)) + '*)\n' +
    'ou um dia dela (ex.: *' + b + brCurto(somaDias(segundaDaSemana(hoje), -12)) + '*)\n\n' +
    '_Esta é a semana ' + semanaIso(hoje) + '_ · *' + b + '0* volta ao menu';
}

/** "Qual setor?" antes de gerar o relatório (pendente = o relatório já escolhido). */
function textoEscolherSetor(pendente, naoEntendi, grupo) {
  var op = SETORES.map(function (st, i) { return EMOJI_NUM[i + 1] + ' ' + st.curto; });
  var b = grupo ? '/' : '';
  return (naoEntendi ? 'Não entendi 🤔\n\n' : '') +
    '🏭 *Qual setor?*\n_' + tituloBase(pendente) + ' · ' + pendente.rotulo + '_\n\n' +
    EMOJI_NUM[0] + ' Todos\n' + op.slice(0, 3).join('   ') + '\n' + op.slice(3).join('   ') + '\n\n' +
    'Pode escolher mais de um (ex.: *' + b + '1 3*)\n*' + b + 'menu* volta ao início';
}

function textoComandos() {
  return '⌨️ *Outros comandos*\n\n' +
    '*semana passada* · *mes* · *mes passado*\n' +
    '*17/11* · um dia\n' +
    '*10/11 a 16/11* · um período\n\n' +
    'Acrescente o setor para detalhar: *semana ibotic*, *ontem uv*\n' +
    '_Setores: tagliabue, ibotic, polimento, uv, colorido_';
}

/** Rodapé das respostas na conversa (no relatório agendado, grupo é indefinido e não vai rodapé). */
function rodape(cmd) {
  if (cmd.grupo === false) return '\n\n_*0* menu · *sair* encerra_';
  if (cmd.grupo === true) return '\n\n_*/0* menu_';
  return '';
}

/** Monta a resposta final. registros = lista devolvida pelo Apps Script (acao listar). */
function responder(cmd, registros, hoje) {
  if (cmd.tipo === 'ajuda') return menu(cmd.naoEntendi, cmd.grupo === true);
  if (cmd.tipo === 'escolherSemana') return textoEscolherSemana(cmd.naoEntendi, cmd.grupo === true, hoje);
  if (cmd.tipo === 'pedirSemana') return textoPedirSemana(cmd.erro, cmd.grupo === true, hoje);
  if (cmd.tipo === 'escolherSetor') return textoEscolherSetor(cmd.pendente, cmd.naoEntendi, cmd.grupo === true);
  if (cmd.tipo === 'aviso') return cmd.msg;
  var texto;
  if (cmd.tipo === 'erro') texto = '⚠️ ' + cmd.msg;
  else if (cmd.tipo === 'comandos') texto = textoComandos();
  else if (cmd.tipo === 'defeitos') texto = relatorioDefeitos(cmd, registros);
  else if (cmd.tipo === 'pendentes') texto = relatorioPendentes(cmd, registros, hoje);
  else texto = relatorioResumo(cmd, registros, hoje);
  return texto + rodape(cmd);
}

// ---------------------------------------------------------------------------
// Painel de gráficos: uma página HTML (só SVG, sem JavaScript nem nada de fora)
// que o Gotenberg transforma em foto PNG. Vai antes do texto nos relatórios de período.
// ---------------------------------------------------------------------------

var COR = { fundo: '#ffffff', texto: '#2C2C2A', sec: '#5F5E5A', fraco: '#888780', grade: '#E6E4DD',
  cartao: '#F4F3EE', barra: '#378ADD', ruim: '#D85A30', defeito: '#7F77DD' };
var LARG = 1080, MARGEM = 56;

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function r1(n) { return Math.round(n * 10) / 10; }

/** Teto "redondo" para o eixo: 1, 2, 2,5 ou 5 × potência de 10. */
function teto(v) {
  if (!(v > 0)) return 1;
  var p = Math.pow(10, Math.floor(Math.log(v) / Math.LN10)), f = v / p;
  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p;
}
function numCurto(n) { return n >= 10000 ? String(Math.round(n / 100) / 10).replace('.', ',') + ' mil' : num(n); }
function corta(s, max) { s = String(s); return s.length > max ? s.slice(0, max - 1).trim() + '…' : s; }

function svgTexto(x, y, s, o) {
  o = o || {};
  return '<text x="' + r1(x) + '" y="' + r1(y) + '" font-size="' + (o.t || 22) + '" fill="' + (o.cor || COR.texto) + '"' +
    (o.ancora ? ' text-anchor="' + o.ancora + '"' : '') + (o.peso ? ' font-weight="' + o.peso + '"' : '') + '>' + esc(s) + '</text>';
}
function svgRet(x, y, w, h, cor, raio) {
  return '<rect x="' + r1(x) + '" y="' + r1(y) + '" width="' + r1(Math.max(0, w)) + '" height="' + r1(Math.max(0, h)) +
    '" rx="' + (raio || 0) + '" fill="' + cor + '"/>';
}
function svgLinha(x1, y1, x2, y2, cor, esp) {
  return '<line x1="' + r1(x1) + '" y1="' + r1(y1) + '" x2="' + r1(x2) + '" y2="' + r1(y2) + '" stroke="' + cor + '" stroke-width="' + (esp || 1) + '"/>';
}

/** Título da seção com legenda (quadradinhos coloridos) alinhada à direita. */
function svgSecao(y, titulo, legenda) {
  var s = [svgTexto(MARGEM, y, titulo, { t: 26, peso: 700 })], x = LARG - MARGEM;
  (legenda || []).slice().reverse().forEach(function (l) {
    s.push(svgTexto(x, y, l[1], { t: 18, cor: COR.sec, ancora: 'end' }));
    x -= l[1].length * 9.5 + 10;
    s.push(svgRet(x - 14, y - 14, 14, 14, l[0], l[2] ? 7 : 2));
    x -= 34;
  });
  return s.join('');
}

/** Agrupa o período por dia (até 35 dias) ou por semana. */
function serieTempo(regs, cmd) {
  var n = dias(cmd.ini, cmd.fim), porSemana = n > 35, grupos = [], idx = {};
  for (var d = cmd.ini; d <= cmd.fim; d = somaDias(d, 1)) {
    var chave = porSemana ? 'S' + semanaIso(d) : d;
    if (!(chave in idx)) {
      idx[chave] = grupos.length;
      grupos.push({ regs: [],
        rotulo: porSemana ? 'S' + semanaIso(d) : (n <= 8 ? DIAS_SEM[diaDaSemana(d)] : String(partes(d).d)),
        rotulo2: porSemana || n <= 8 ? brCurto(d) : '' });
    }
    idx[d] = idx[chave];
  }
  regs.forEach(function (r) { if (r.data in idx) grupos[idx[r.data]].regs.push(r); });
  grupos.forEach(function (g) { g.a = agrega(g.regs); });
  return grupos;
}

/** Rótulo do eixo: inteiro sem casas, fração com uma casa (eixo de 0 a 10 tem 2,5). */
function eixo(v) { return v % 1 ? String(r1(v)).replace('.', ',') : numCurto(v); }

/** Colunas de produção (pilhas ou peças) por dia ou por semana. */
function svgTempo(x, y, w, h, grupos, pilhas) {
  var s = [], n = grupos.length;
  var vals = grupos.map(function (g) { return pilhas ? g.a.pilhas : g.a.pecas; });
  var maxV = teto(Math.max.apply(null, vals.concat([0])));
  var px = x + 80, pw = w - 100, ph = h - 64, base = y + ph, hb = ph - 34;

  for (var i = 0; i <= 4; i++) {
    var yy = base - hb * i / 4;
    s.push(svgLinha(px, yy, px + pw, yy, i ? COR.grade : COR.fraco, i ? 1 : 1.5));
    s.push(svgTexto(px - 12, yy + 6, eixo(maxV * i / 4), { t: 17, cor: COR.sec, ancora: 'end' }));
  }

  var slot = pw / n, bw = Math.min(slot * 0.62, 96), passo = n > 20 ? 2 : 1, tv = n > 8 ? 16 : 18;
  grupos.forEach(function (g, i) {
    var cx = px + slot * i + slot / 2, bh = hb * vals[i] / maxV;
    s.push(svgRet(cx - bw / 2, base - bh, bw, bh, COR.barra, n > 20 ? 2 : 4));
    if (n <= 12 && vals[i] > 0) {
      s.push(bh > 40 ? svgTexto(cx, base - bh + 28, numCurto(vals[i]), { t: tv, cor: '#ffffff', ancora: 'middle', peso: 700 })
                     : svgTexto(cx, base - bh - 10, numCurto(vals[i]), { t: tv, cor: COR.sec, ancora: 'middle' }));
    }
    if (i % passo === 0) {
      s.push(svgTexto(cx, base + 28, g.rotulo, { t: n > 20 ? 16 : 19, cor: COR.texto, ancora: 'middle' }));
      if (g.rotulo2) s.push(svgTexto(cx, base + 52, g.rotulo2, { t: 16, cor: COR.sec, ancora: 'middle' }));
    }
  });
  if (!vals.some(function (v) { return v > 0; })) {
    s.push(svgTexto(px + pw / 2, y + ph / 2, 'Sem produção lançada no período', { t: 22, cor: COR.sec, ancora: 'middle' }));
  }
  return s.join('');
}

/** Colunas simples com o valor em cima (peças ruins por setor ou por turno). */
function svgColunas(x, y, w, h, itens) {
  var s = [], n = itens.length, ph = h - 78, base = y + ph;
  var maxV = Math.max.apply(null, itens.map(function (it) { return it.valor || 0; }).concat([1])); // a maior coluna ocupa a altura toda
  var slot = w / n, bw = Math.min(slot * 0.5, 130);
  s.push(svgLinha(x, base, x + w, base, COR.fraco, 1.5));
  itens.forEach(function (it, i) {
    var cx = x + slot * i + slot / 2, bh = it.valor ? (ph - 30) * it.valor / maxV : 0;
    if (bh) s.push(svgRet(cx - bw / 2, base - bh, bw, bh, COR.ruim, 4));
    s.push(svgTexto(cx, base - bh - 10, it.texto, { t: it.valor !== null ? 22 : 18, cor: it.valor !== null ? COR.texto : COR.fraco,
      ancora: 'middle', peso: it.valor !== null ? 700 : null }));
    it.rotulo.forEach(function (l, j) { s.push(svgTexto(cx, base + 28 + j * 22, l, { t: 18, ancora: 'middle', peso: j ? null : 700 })); });
    if (it.sub) s.push(svgTexto(cx, base + 28 + it.rotulo.length * 22, it.sub, { t: 16, cor: COR.sec, ancora: 'middle' }));
  });
  return s.join('');
}

/** Barras deitadas: ranking de defeitos. Devolve { svg, altura }. */
function svgRanking(x, y, w, itens, total) {
  var s = [], linha = 54, rotW = 430, numW = 150, bw = w - rotW - numW;
  var max = Math.max.apply(null, itens.map(function (it) { return it[1]; }).concat([1]));
  itens.forEach(function (it, i) {
    var yy = y + i * linha;
    s.push(svgTexto(x, yy + 30, it[0], { t: 20, peso: 700 }));
    s.push(svgTexto(x + 70, yy + 30, corta(DEFEITOS[it[0]] || '', 30), { t: 20, cor: COR.sec }));
    var l = Math.max(4, bw * it[1] / max);
    s.push(svgRet(x + rotW, yy + 10, l, 30, COR.defeito, 4));
    s.push(svgTexto(x + rotW + l + 12, yy + 32, num(it[1]) + (total ? ' · ' + Math.round(100 * it[1] / total) + '%' : ''), { t: 19, cor: COR.sec }));
  });
  return { svg: s.join(''), altura: itens.length * linha };
}

function svgCartao(x, y, w, rotulo, valor, cor) {
  return svgRet(x, y, w, 118, COR.cartao, 14) + svgTexto(x + 22, y + 40, rotulo, { t: 19, cor: COR.sec }) +
    svgTexto(x + 22, y + 92, valor, { t: 38, peso: 700, cor: cor || COR.texto });
}

/** Separa nomes longos em duas linhas ("MADEIRADO" / "COLORIDO"). */
function nomeEmLinhas(nome) { var p = nome.split(' '); return p.length > 1 ? [p[0], p.slice(1).join(' ')] : [nome]; }

/**
 * Painel com os gráficos de um relatório de período.
 * Retorna null quando não cabe gráfico (um dia só, ajuda, pendentes ou nada lançado),
 * ou { html, largura, altura, legenda } para o Gotenberg desenhar e o WAHA mandar como foto.
 *
 * Produção em pilhas, que é como quase todos os setores lançam. Só vira peças quando não há
 * nenhuma pilha no que foi pedido (ex.: só a IBOTIC). As peças de quem conta em peças aparecem
 * à parte no cartão ("+ 2.150 pç"), sem somar pilha com peça.
 */
function graficoRelatorio(cmd, registros) {
  if (!cmd || (cmd.tipo !== 'resumo' && cmd.tipo !== 'defeitos') || cmd.ini === cmd.fim) return null;
  var regs = filtrar(registros, cmd);
  if (!regs.length) return null;
  var total = agrega(regs), s = sel(cmd), um = unico(cmd);
  var pilhas = total.pilhas > 0 || !total.pecas;
  // Vários setores: o título fica curto e os setores vão na linha de baixo.
  var titulo = s && !um ? tituloBase(cmd) : tituloDe(cmd);
  var sub = cmd.rotulo + (s && !um ? ' · ' + lista(s.map(curtoSetor)) : '');
  var out = [], y, W = LARG - 2 * MARGEM;

  out.push(svgTexto(MARGEM, 88, corta(titulo, 40), { t: 44, peso: 700 }));
  out.push(svgTexto(MARGEM, 132, corta(sub, 72), { t: 26, cor: COR.sec }));

  var cw = (W - 2 * 18) / 3, extra = pilhas && total.pecas ? ' · + ' + numCurto(total.pecas) + ' pç' : '';
  out.push(svgCartao(MARGEM, 168, cw, 'Produção' + extra,
    pilhas ? num(total.pilhas) + (total.pilhas === 1 ? ' pilha' : ' pilhas') : num(total.pecas) + ' pç'));
  out.push(svgCartao(MARGEM + (cw + 18), 168, cw, 'Peças ruins', num(total.ruins), COR.ruim));
  out.push(svgCartao(MARGEM + 2 * (cw + 18), 168, cw, 'Lançamentos', num(total.n)));

  var grupos = serieTempo(regs, cmd), porSemana = dias(cmd.ini, cmd.fim) > 35;
  y = 362;
  out.push(svgSecao(y, 'Produção por ' + (porSemana ? 'semana' : 'dia'), [[COR.barra, pilhas ? 'pilhas' : 'peças']]));
  out.push(svgTempo(MARGEM, y + 34, W, 380, grupos, pilhas));
  y += 34 + 380 + 64;

  function item(a, rotulo) {
    return { valor: a.n ? a.ruins : null, texto: a.n ? num(a.ruins) : 'sem lanç.', rotulo: rotulo, sub: a.n ? lancamentos(a.n) : '' };
  }
  var itens, tituloB;
  if (um) {
    tituloB = 'Peças ruins por turno';
    itens = ['Dia', 'Noite'].map(function (t) { return item(agrega(regs.filter(function (r) { return r.turno === t; })), [t]); });
  } else {
    tituloB = 'Peças ruins por setor';
    itens = SETORES.filter(function (st) { return !s || s.indexOf(st.id) >= 0; }).map(function (st) {
      return item(agrega(regs.filter(function (r) { return r.setor === st.id; })), nomeEmLinhas(st.nome));
    });
  }
  out.push(svgSecao(y, tituloB));
  out.push(svgColunas(MARGEM, y + 34, W, 290, itens));
  y += 34 + 290 + 60;

  var top = topDefeitos(total.defeitos, 6);
  out.push(svgSecao(y, 'Principais defeitos'));
  if (top.length) {
    var rk = svgRanking(MARGEM, y + 20, W, top, total.ruins);
    out.push(rk.svg);
    y += 20 + rk.altura;
  } else {
    out.push(svgTexto(MARGEM, y + 56, 'Nenhum defeito lançado no período.', { t: 22, cor: COR.sec }));
    y += 72;
  }
  y += 40;
  out.push(svgLinha(MARGEM, y, LARG - MARGEM, y, COR.grade, 1));
  out.push(svgTexto(MARGEM, y + 36, 'Apontamento Buy Off · produção em ' + (pilhas ? 'pilhas' : 'peças') +
    (extra ? ' (lançamentos em peças à parte)' : ''), { t: 17, cor: COR.fraco }));
  var H = Math.ceil(y + 64);

  var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + LARG + '" height="' + H + '" viewBox="0 0 ' + LARG + ' ' + H +
    '" font-family="Liberation Sans, DejaVu Sans, Arial, sans-serif">' + svgRet(0, 0, LARG, H, COR.fundo) + out.join('') + '</svg>';
  var html = '<!doctype html><html><head><meta charset="utf-8"><style>html,body{margin:0;padding:0;background:#fff}' +
    'body{width:' + LARG + 'px;height:' + H + 'px;overflow:hidden}svg{display:block}</style></head><body>' + svg + '</body></html>';
  return { html: html, largura: LARG, altura: H, legenda: '📈 ' + tituloDe(cmd) + ' · gráficos' };
}

// ---------------------------------------------------------------------------
// WhatsApp: quem mandou e se pode receber os números
// ---------------------------------------------------------------------------

/** Variantes de um número brasileiro com e sem o 9 do celular (o WhatsApp às vezes guarda sem). */
function variantesNumero(dig) {
  var v = [dig];
  if (/^55\d{2}9\d{8}$/.test(dig)) v.push(dig.slice(0, 4) + dig.slice(5));
  if (/^55\d{2}[6-9]\d{7}$/.test(dig)) v.push(dig.slice(0, 4) + '9' + dig.slice(4));
  return v;
}

/** Lê a lista de autorizados: números (só dígitos) ou ids completos (…@c.us, …@lid, …@g.us). */
function lerAutorizados(texto) {
  var ids = {}, numeros = {};
  String(texto || '').split(/[,;\s]+/).filter(Boolean).forEach(function (x) {
    x = x.toLowerCase();
    if (x.indexOf('@') >= 0) ids[x] = true;
    else { var d = x.replace(/\D/g, ''); if (d.length >= 10) variantesNumero(d).forEach(function (v) { numeros[v] = true; }); }
  });
  return { ids: ids, numeros: numeros };
}

/** Todos os ids que podem identificar quem escreveu (o formato muda conforme o engine do WAHA). */
function idsRemetente(p) {
  var c = [p.participant, p.author, p.from];
  var dk = (p._data && p._data.key) || {};
  c.push(dk.participant, dk.participantAlt, dk.participantPn, dk.senderPn, dk.remoteJid, dk.remoteJidAlt);
  var inf = (p._data && p._data.Info) || {};
  c.push(inf.Sender, inf.SenderAlt);
  if (p._data && p._data.id) c.push(p._data.id.participant);
  return c.filter(function (x) { return typeof x === 'string' && x && !/@g\.us$/.test(x) && !/@broadcast$/.test(x); })
    .map(function (x) { return x.toLowerCase().replace(/:\d+(?=@)/, ''); });
}

function autorizado(aut, chatId, remetentes) {
  if (aut.ids[String(chatId).toLowerCase()]) return true;
  return remetentes.some(function (id) {
    if (aut.ids[id]) return true;
    if (/@lid$/.test(id)) return false; // id interno do WhatsApp, não é telefone
    var d = id.split('@')[0].replace(/\D/g, '');
    return !!aut.numeros[d];
  });
}

/**
 * Decide o que fazer com um evento do WAHA.
 * Retorna null (ignorar) ou { chatId, texto, msgId } quando é para responder.
 */
function lerEvento(ev, autorizadosTexto) {
  if (!ev || (ev.event !== 'message' && ev.event !== 'message.any')) return null;
  var p = ev.payload || {};
  if (p.fromMe) return null;
  var texto = typeof p.body === 'string' ? p.body.trim() : '';
  if (!texto || texto.length > 200) return null;
  var chatId = String(p.from || '');
  if (!chatId || /@broadcast$/.test(chatId) || /@newsletter$/.test(chatId)) return null;
  var grupo = /@g\.us$/.test(chatId);
  if (grupo && !/^[\/!]/.test(texto)) return null; // em grupo só responde a comandos com barra
  var rem = idsRemetente(p);
  if (!autorizado(lerAutorizados(autorizadosTexto), chatId, rem)) return { negado: true, chatId: chatId, remetentes: rem };
  return { chatId: chatId, texto: texto, msgId: p.id || null };
}

// ===================== nó: Montar resposta =====================
const res = $input.first().json || {};
const hoje = hojeISO();
let regs = null, erro = null;
if (res.ok === true && Array.isArray(res.registros)) regs = res.registros;
else if (res.erro === "chave_invalida") erro = "A chave de controle do chatbot está errada (BUYOFF_CHAVE_CONTROLE no .env).";
else erro = "Não consegui ler a planilha agora. Tente de novo em alguns minutos.";

const saida = [];
for (const it of $("Interpretar").all()) {
  const c = it.json;
  const base = { session: c.session, chatId: c.chatId, replyTo: c.replyTo || null };
  const precisaDados = ["resumo", "defeitos", "pendentes"].indexOf(c.cmd.tipo) >= 0;
  if (precisaDados && erro) {
    if (c.agendado) throw new Error("Relatório agendado não enviado: " + erro + " Resposta: " + JSON.stringify(res).slice(0, 300));
    saida.push({ json: Object.assign(base, { text: "⚠️ " + erro }) });
    continue;
  }
  if (c.pularSeVazio && !filtrar(regs, c.cmd).length) continue;
  const json = Object.assign(base, { text: responder(c.cmd, regs, hoje), temGrafico: false });
  // Relatório de período: vai também uma foto com gráficos (o Gotenberg desenha o HTML).
  const g = regs ? graficoRelatorio(c.cmd, regs) : null;
  if (!g) { saida.push({ json }); continue; }
  Object.assign(json, { temGrafico: true, largura: g.largura, altura: g.altura, legenda: g.legenda });
  saida.push({ json, binary: { html: { data: Buffer.from(g.html, "utf8").toString("base64"),
    mimeType: "text/html", fileName: "index.html", fileExtension: "html" } } });
}
return saida;
